/** The book modules, each `{ BOOK, RULES }`. */
export const BOOKS = Object.freeze([ai, ftd, mpmm, phb, tce, xge, xmm, xphb]);

/** Every rule of the pack, with its book, page, kind and status. @type {readonly import("./book.mjs").Rule[]} */
